package com.noslop.mvp

/**
 * A file the user picked to attach to a post (Roadmap #6c). [path] is a readable absolute path (the
 * platform copies the picked asset somewhere we can open); [thumbnailB64] is a pre-scaled ~90 px JPEG
 * (base64, NO_WRAP) generated by the platform — the same in-band preview Android posts carry.
 */
data class PickedMedia(
    val path: String,
    val mimeType: String,
    val size: Long,
    val thumbnailB64: String?,
)

/**
 * Platform photo picker — PHPicker on iOS (Swift bridge, needs no photo-library permission),
 * AWT FileDialog on desktop, unavailable in the Android shell. [pick]'s callback gets null on cancel.
 */
expect object ImagePicker {
    val isAvailable: Boolean
    fun pick(onResult: (PickedMedia?) -> Unit)
}
